 baseCurrency: string,
 targetCurrency?: string
): Promise {
 targetCurrency = targetCurrency ?? "BZD";
 const apiKey = process.env.EXCHANGE\\_RATES\\_API\\_KEY as string;
 const url = `https://api.exchangeratesapi.io/latest?access\\_key=${apiKey}&base=${baseCurrency}&symbols=${targetCurrency ?? "BZD"}`;

