 return 1; // Return a default rate of 1 if there is an error
 }
}
// In-memory cache for exchange rates
const exchangeRateCache = new Map();

async function getExchangeRateAsync(baseCurrency: string, targetCurrency?: string): Promise {
 // targetCurrency is optional, default to BZD
 targetCurrency = targetCurrency ?? 'BZD';
 const cacheKey = `${baseCurrency}\\_${targetCurrency}`;
 const now = Date.now();
 const oneDay = 24 \\* 60 \\* 60 \\* 1000; // In milliseconds

 // Check if the rate is in the cache and is not older than one day
 if (exchangeRateCache.has(cacheKey) && now - exchangeRateCache.get(cacheKey)!.timestamp < oneDay) {
 return exchangeRateCache.get(cacheKey)!.rate;
 }

 // If the rate is not in the cache or is older than one day, fetch it from the API
 const apiKey = process.env.EXCHANGE\\_RATES\\_API\\_KEY as string;
 const url = `https://api.exchangeratesapi.io/latest?access\\_key=${apiKey}&base=${baseCurrency}&symbols=${targetCurrency}`;

 try {
 const response = await fetch(url);
 // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
 const data = await response.json();

 // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
 if (data.error) {
 // eslint-disable-next-line @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unsafe-member-access
 throw new Error(data.error.info);
 }

 // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-member-access
 const rate = data.rates[targetCurrency];

 // Store the fetched rate in the cache with the current timestamp
 // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
 exchangeRateCache.set(cacheKey, { rate, timestamp: now });

 return rate as number;
 } catch (error) {
 console.error('Error fetching exchange rate:', error);
 return 1; // Return a default rate of 1 if there is an error
 }
}

