 paragraphs = ann["paragraphs"]
 for paragraph in paragraphs:
 lines = paragraph["lines"]
 for line in lines:
 words = line["words"]
 for word in words:
 word\\_list = [word["text"], word["vertices"], image\\_id, ann["image\\_id"], word["legible"], word["vertical"]]
 flattened\\_words.append(word\\_list)
 image\\_id += 1
 return flattened\\_words
