 df = pd.DataFrame(flattened\\_words, columns=["text", "vertices", "index\\_image", "image\\_id", "legible", "vertical"])
 df = df.reindex(columns=["image\\_id", "text", "vertices", "index\\_image", "legible", "vertical"])
